import"./chunk-2NFLSA4Y.js";var a={forcedOscillations:{theory:{concept:"[[Forced oscillations are oscillations caused by an external periodic force.]] Once the motion settles, the system oscillates at the frequency of the driving force, not at its own natural frequency, with an amplitude that depends on how close the two frequencies are. Resonance is the sharp growth of the amplitude when the driving frequency approaches the natural frequency. Damping takes energy away and limits how large the amplitude at resonance can become."},section:{drive:{title:"Repeated pushes",text:"The force alternates left and right as F\u2080 sin(2\u03C0ft). The fixed anchor stays still: the force acts directly on the cart. A higher F\u2080 gives a larger response."},resonance:{title:"Finding resonance",text:"The natural frequency is set by stiffness and mass. With weak damping, driving near it produces a large response. The exact displacement-amplitude peak is slightly below the natural frequency when damping is present."},damping:{title:"Energy loss",text:"[[The damping force opposes velocity.]] More damping lowers and broadens the resonance peak. If b\xB2 \u2265 2mk, there is no nonzero-frequency displacement peak; the resonant-frequency reading is then 0."},transient:{title:"Starting and settling",text:"The cart starts at rest. Its first swings combine a decaying free oscillation with the driven response. The predicted steady amplitude and phase lag describe the eventual motion, not the first swing. Changing a setup control restarts the experiment."},energy:{title:"Energy in and out",text:"The drive can add or take back energy: its power is Fv. Damping always removes energy at rate bv\xB2. [[Once settled, the energy supplied per cycle equals the energy lost.]] The cart displacement lags the driving force."}},param:{frequency:"Driving frequency",force:"Driving-force amplitude",damping:"Damping coefficient",mass:"Cart mass",stiffness:"Spring stiffness",timeStep:"Time step"},hint:{frequency:"Compare with f\u2080 in the readings. The near-resonance preset assumes the default mass and spring.",force:"This is the maximum force, not the displacement amplitude.",damping:"Higher damping removes more energy. This experiment always has some damping.",stiffness:"A stiffer spring raises the natural frequency."},preset:{slow:"Slow \xB7 0.30 Hz",near:"Near default resonance \xB7 0.71 Hz",fast:"Fast \xB7 1.50 Hz"},measure:{displacement:"Displacement from equilibrium",amplitude:"Steady amplitude (predicted)",natural:"Natural frequency",peak:"Largest |x| sampled so far",phase:"Steady phase lag",drive:"Driving force now",gain:"Amplitude / static displacement F\u2080/k",resonant:"Amplitude-peak frequency (0: no peak)",input:"Power from the drive",loss:"Power lost to damping"},graph:{displacement:"Displacement over time",force:"Driving force over time",power:"Power supplied and dissipated"},view:{drive:"Driving force: {value}",frequencies:"Drive: {drive} \xB7 Natural: {natural}",scale:"Schematic rig \xB7 1 scene unit = {value}",equilibrium:"Equilibrium \xB7 x = 0",forceOption:"Driving-force arrow"},formula:{natural:"Natural frequency without damping",drive:"Periodic driving force",motion:"Equation of motion",amplitude:"Steady displacement amplitude; \u03C9 = 2\u03C0f",resonant:"Amplitude-peak frequency, only if k/m > b\xB2/(2m\xB2)"},variable:{omega:"Angular driving frequency"},assumption:{linear:"A massless spring obeys Hooke\u2019s law throughout the shown range; nonlinear behaviour and breaking are ignored.",axis:"The cart is a point mass moving along one horizontal axis; the ideal guide balances gravity.",damping:"Only viscous damping \u2212bv is included, with b > 0. Dry friction and collisions are omitted.",drive:"An ideal source applies a sinusoidal force directly to the cart; the anchor does not move.",initial:"Every setup starts at x = 0 and v = 0. The amplitude and phase predictions describe settled motion.",drawing:"The rig and coils are schematic, not to scale. Displacement always uses the same scene scale, shown in the scene; the camera and guide expand for large motion. Compare physical amplitudes in the readings. The drawn coil count is illustrative."},challenge:{resonance:{title:"Find a strong response",description:"Make the predicted steady amplitude at least 4 times F\u2080/k.",hint:"Move the drive frequency close to the natural frequency and reduce damping."},quiet:{title:"Small response",description:"Make the predicted steady amplitude less than half of F\u2080/k.",hint:"Try a driving frequency well above the natural frequency."},motion:{title:"Build up the motion",description:"After at least 2 seconds, record a displacement of at least 0.25 m.",hint:"Drive near resonance and allow the motion to build."},phase:{title:"A quarter-cycle behind",description:"Make the steady phase lag fall within 3\xB0 of 90\xB0.",hint:"Match the drive frequency to the natural frequency."},damped:{title:"Remove the amplitude peak",description:"Find a setup with no nonzero-frequency displacement peak.",hint:"Increase damping until b\xB2 \u2265 2mk."}}}},i={sim:a};export{i as default,a as sim};
